class FrontMiddleBackQueue {
    private static final class Node {
        int value;
        Node prev;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    private final Node head = new Node(0);
    private final Node tail = new Node(0);
    private int size;

    public FrontMiddleBackQueue() {
        head.next = tail;
        tail.prev = head;
    }

    public void pushFront(int val) {
        insertAfter(head, new Node(val));
    }

    public void pushMiddle(int val) {
        if (size == 0) {
            insertBefore(tail, new Node(val));
        } else {
            insertBefore(nodeAt(size / 2), new Node(val));
        }
    }

    public void pushBack(int val) {
        insertBefore(tail, new Node(val));
    }

    public int popFront() {
        return size == 0 ? -1 : remove(head.next);
    }

    public int popMiddle() {
        return size == 0 ? -1 : remove(nodeAt((size - 1) / 2));
    }

    public int popBack() {
        return size == 0 ? -1 : remove(tail.prev);
    }

    private Node nodeAt(int index) {
        if (index < size / 2) {
            Node current = head.next;
            for (int i = 0; i < index; i++) {
                current = current.next;
            }
            return current;
        }
        Node current = tail.prev;
        for (int i = size - 1; i > index; i--) {
            current = current.prev;
        }
        return current;
    }

    private void insertAfter(Node left, Node node) {
        Node right = left.next;
        left.next = node;
        node.prev = left;
        node.next = right;
        right.prev = node;
        size++;
    }

    private void insertBefore(Node right, Node node) {
        insertAfter(right.prev, node);
    }

    private int remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
        size--;
        return node.value;
    }
}

