        insert(size(root) / 2, val);
    }

    public void pushBack(int val) {
        insert(size(root), val);
    }

    public int popFront() {
        return size(root) == 0 ? -1 : removeAt(0);
    }

    public int popMiddle() {
        return size(root) == 0 ? -1 : removeAt((size(root) - 1) / 2);
    }

    public int popBack() {
        return size(root) == 0 ? -1 : removeAt(size(root) - 1);
    }

    private void insert(int index, int value) {
        Node node = new Node(value, nextPriority());
        Node[] parts = split(root, index);
        root = merge(merge(parts[0], node), parts[1]);
    }

    private int removeAt(int index) {
        Node[] first = split(root, index);
        Node[] second = split(first[1], 1);
        int value = second[0].value;
        root = merge(first[0], second[1]);
        return value;
    }

    private Node[] split(Node node, int leftCount) {
        if (node == null) {
            return new Node[] {null, null};
        }
        if (size(node.left) >= leftCount) {
            Node[] parts = split(node.left, leftCount);
            node.left = parts[1];
            update(node);
            parts[1] = node;
            return parts;
        }
        Node[] parts = split(node.right, leftCount - size(node.left) - 1);
        node.right = parts[0];
        update(node);
        parts[0] = node;
        return parts;
    }

    private Node merge(Node a, Node b) {
        if (a == null) {
            return b;
        }
        if (b == null) {
            return a;
        }
        if (a.priority > b.priority) {
            a.right = merge(a.right, b);
            update(a);
            return a;
        }
        b.left = merge(a, b.left);
        update(b);
        return b;
    }

    private int nextPriority() {
        seed = seed * 1103515245 + 12345;
        return seed;
    }

    private int size(Node node) {
        return node == null ? 0 : node.size;
    }

    private void update(Node node) {
        node.size = 1 + size(node.left) + size(node.right);
    }
