            right.addFirst(left.removeLast());
        }
        while (left.size() < right.size()) {
            left.addLast(right.removeFirst());
        }
    }

    private static final class IntDeque {
        private final int[] data = new int[4096];
        private int head = 2048;
        private int tail = 2048;

        int size() {
